package com.naang360.redmi3dscanner;
import android.Manifest;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.google.ar.core.*;import com.google.ar.core.exceptions.*;import java.io.*;
public class MainActivity extends AppCompatActivity {private static final int CAM=10;private Session s;private boolean scanning;private boolean installRequested;private SensorFusion fusion;private TextView status,sensors,root;private ScannerView view;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);sensors=findViewById(R.id.sensors);root=findViewById(R.id.root);view=findViewById(R.id.scannerView);fusion=new SensorFusion(this);sensors.setText("Accelerometer "+fusion.hasAccelerometer()+" • Gyro "+fusion.hasGyroscope()+" • Magnetometer "+fusion.hasMagnetometer());root.setText("Root: "+(RootAccess.isRootAvailable()?"available":"optional/unavailable"));Button scan=findViewById(R.id.scanButton);scan.setOnClickListener(v->{scanning=!scanning;scan.setText(scanning?"STOP SCAN":"START SCAN");status.setText(scanning?"Scanning…":"Paused");});findViewById(R.id.exportButton).setOnClickListener(v->exportPly());if(checkSelfPermission(Manifest.permission.CAMERA)!=0)requestPermissions(new String[]{Manifest.permission.CAMERA},CAM);else startAr();}private void startAr(){try{if(ArCoreApk.getInstance().requestInstall(this,!installRequested)==ArCoreApk.InstallStatus.INSTALL_REQUESTED){installRequested=true;return;}s=new Session(this);Config c=s.getConfig();c.setPlaneFindingMode(Config.PlaneFindingMode.HORIZONTAL_AND_VERTICAL);s.configure(c);s.resume();status.setText("Tracking ready • depth API optional");new Thread(this::loop).start();}catch(Exception e){status.setText("AR startup: "+e.getClass().getSimpleName());}}private void loop(){while(!isFinishing()&&s!=null){try{if(!scanning){Thread.sleep(80);continue;}Frame f=s.update();if(f.getCamera().getTrackingState()!=TrackingState.TRACKING)continue;PointCloud pc=f.acquirePointCloud();float[] a=new float[pc.getPoints().remaining()];pc.getPoints().get(a);for(int i=0;i+3<a.length;i+=4)view.cloud().add(a[i],a[i+1],a[i+2]);pc.release();runOnUiThread(()->{status.setText("Scanning • "+view.cloud().size()+" points");view.invalidate();});}catch(Exception e){try{Thread.sleep(30);}catch(Exception ignored){}}}}private void exportPly(){try{File d=getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS);File f=new File(d,"scan-"+System.currentTimeMillis()+".ply");view.cloud().writePly(f);Toast.makeText(this,"Saved "+f,Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Export failed: "+e.getMessage(),Toast.LENGTH_LONG).show();}}protected void onPause(){super.onPause();if(s!=null)s.pause();}protected void onDestroy(){if(fusion!=null)fusion.close();if(s!=null)s.close();super.onDestroy();}}